use super::REMOTE_ROOT;

/// The probe script, pure so its shape can be pinned by a test.
///
/// **IT MUST NOT END IN A PIPE, and this is not style.** The first version was
/// `… --version 2>&1 | head -3`, and a shell pipeline exits with the status of its LAST command — so
/// `head` succeeding masked anything the binary did. MEASURED against a deliberately truncated binary
/// on a real device: raw exit **139 (SIGSEGV)**, through the pipeline **exit 0**. The probe could never
/// fail, which made the entire rollback path dead code while every test around it passed.
///
/// So the output is captured first, `$?` is read immediately, and the script exits with it. `head` is
/// still there to bound what comes back, but it runs where it cannot swallow the verdict.
pub fn probe_script(name: &str) -> String {
    format!(
        "out=$($HOME/{REMOTE_ROOT}/{name}.current --version 2>&1); rc=$?; \
         printf '%s\\n' \"$out\" | head -3; echo \"rc=$rc\""
    )
}
